#include <cctype>
#include <map>
#include <optional>
#include <string>
#include <vector>

struct Match { int status; std::string handler; std::map<std::string, std::string> params; std::string allow; };

static std::vector<std::string> split(const std::string& path)
{
    std::vector<std::string> parts;
    std::size_t start{ 0 };
    while (start <= path.size())
    {
        const std::size_t slash{ path.find('/', start) };
        parts.push_back(path.substr(start, slash == std::string::npos ? std::string::npos : slash - start));
        if (slash == std::string::npos) break;
        start = slash + 1;
    }
    return parts;
}

static int hexValue(char c)
{
    if (c >= '0' && c <= '9') return c - '0';
    if (c >= 'a' && c <= 'f') return c - 'a' + 10;
    if (c >= 'A' && c <= 'F') return c - 'A' + 10;
    return -1;
}

static std::optional<std::string> decode(const std::string& text)
{
    std::string out;
    for (std::size_t i{ 0 }; i < text.size(); ++i)
    {
        if (text[i] != '%') { out += text[i]; continue; }
        if (i + 2 >= text.size()) return std::nullopt;
        const int hi{ hexValue(text[i + 1]) }, lo{ hexValue(text[i + 2]) };
        if (hi < 0 || lo < 0) return std::nullopt;
        out += static_cast<char>(hi * 16 + lo);
        i += 2;
    }
    return out;
}

class Router
{
public:
    void add(const std::string& method, const std::string& pattern, const std::string& handler)
    {
        routes.push_back({ method, split(pattern), handler });
    }

    Match route(const std::string& method, const std::string& path) const
    {
        const std::vector<std::string> parts{ split(path) };
        const Route* best{ nullptr };
        int bestExact{ -1 };
        std::map<std::string, std::string> bestParams;
        std::string allow;
        for (const Route& r : routes)
        {
            std::map<std::string, std::string> params;
            int exact{ 0 };
            if (!matches(r, parts, params, exact)) continue;
            if (r.method != method)
            {
                if (allow.find(r.method) == std::string::npos) allow += (allow.empty() ? "" : ", ") + r.method;
                continue;
            }
            if (exact > bestExact) { best = &r; bestExact = exact; bestParams = params; }
        }
        if (best) return { 200, best->handler, bestParams, "" };
        if (!allow.empty()) return { 405, "", {}, allow };
        return { 404, "", {}, "" };
    }

private:
    struct Route { std::string method; std::vector<std::string> parts; std::string handler; };
    std::vector<Route> routes;

    static bool matches(const Route& r, const std::vector<std::string>& parts, std::map<std::string, std::string>& params, int& exact)
    {
        if (r.parts.size() != parts.size()) return false;
        for (std::size_t i{ 0 }; i < parts.size(); ++i)
        {
            const std::string& p{ r.parts[i] };
            if (p.size() >= 2 && p.front() == '{' && p.back() == '}')
            {
                const auto value{ decode(parts[i]) };
                if (parts[i].empty() || !value) return false;
                params[p.substr(1, p.size() - 2)] = *value;
            }
            else if (p == parts[i]) ++exact;
            else return false;
        }
        return true;
    }
};

std::optional<std::string> safeRelativePath(const std::string& urlPath)
{
    if (urlPath.empty() || urlPath[0] != '/') return std::nullopt;
    const auto decoded{ decode(urlPath) };
    if (!decoded) return std::nullopt;
    for (char c : *decoded) if (c == '\\' || c == ':' || c == '\0') return std::nullopt;
    std::vector<std::string> kept;
    for (const std::string& seg : split(decoded->substr(1)))
    {
        if (seg.empty() || seg == ".") continue;
        if (seg == "..") { if (kept.empty()) return std::nullopt; kept.pop_back(); continue; }
        if (seg[0] == '.' || seg.back() == '.' || seg.back() == ' ') return std::nullopt;
        std::string stem{ seg.substr(0, seg.find('.')) };
        for (char& c : stem) c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
        static const char* const devices[]{ "con", "prn", "aux", "nul" };
        for (const char* d : devices) if (stem == d) return std::nullopt;
        if (stem.size() == 4 && (stem.rfind("com", 0) == 0 || stem.rfind("lpt", 0) == 0) && stem[3] >= '1' && stem[3] <= '9') return std::nullopt;
        kept.push_back(seg);
    }
    if (kept.empty()) return std::string("index.html");
    std::string out;
    for (std::size_t i{ 0 }; i < kept.size(); ++i) out += (i ? "/" : "") + kept[i];
    return out;
}

unitTests:
TEST("routing with parameters") {
    Router r;
    r.add("GET", "/", "home");
    r.add("GET", "/courses/{id}", "course");
    r.add("GET", "/courses/new", "newCourse");
    r.add("GET", "/courses/{id}/lessons/{lesson}", "lesson");
    r.add("POST", "/courses/{id}", "updateCourse");
    const Match a{ r.route("GET", "/courses/networking") };
    CHECK_EQ(a.status, 200); CHECK_EQ(a.handler, std::string("course")); CHECK_EQ(a.params.at("id"), std::string("networking"));
    CHECK_EQ(r.route("GET", "/courses/new").handler, std::string("newCourse"));
    const Match l{ r.route("GET", "/courses/c%2B%2B/lessons/2.03") };
    CHECK_EQ(l.handler, std::string("lesson"));
    if (l.status == 200) { CHECK_EQ(l.params.at("id"), std::string("c++")); CHECK_EQ(l.params.at("lesson"), std::string("2.03")); }
    CHECK_EQ(r.route("GET", "/").handler, std::string("home"));
}
TEST("404 and 405") {
    Router r;
    r.add("GET", "/api/progress", "get");
    r.add("PUT", "/api/progress", "put");
    CHECK_EQ(r.route("GET", "/nothing").status, 404);
    CHECK_EQ(r.route("GET", "/api/progress/extra").status, 404);
    const Match m{ r.route("DELETE", "/api/progress") };
    CHECK_EQ(m.status, 405);
    CHECK_EQ(m.allow, std::string("GET, PUT"));
    Router p;
    p.add("GET", "/u/{name}", "user");
    CHECK_EQ(p.route("GET", "/u/").status, 404);
    CHECK_EQ(p.route("GET", "/u/%zz").status, 404);
}
TEST("safe paths") {
    CHECK_EQ(safeRelativePath("/images/logo.png").value_or("?"), std::string("images/logo.png"));
    CHECK_EQ(safeRelativePath("/").value_or("?"), std::string("index.html"));
    CHECK_EQ(safeRelativePath("/a/./b/../c.css").value_or("?"), std::string("a/c.css"));
    CHECK_EQ(safeRelativePath("//docs//guide.html").value_or("?"), std::string("docs/guide.html"));
    CHECK_EQ(safeRelativePath("/my%20page.html").value_or("?"), std::string("my page.html"));
}
TEST("traversal and Windows tricks are refused") {
    for (const char* bad : { "/../../Windows/win.ini", "/images/..%2F..%2F..%2Fsecret.txt", "/images/..\\..\\config.json",
                             "/a/../../x", "/C:/Windows", "/file.txt::$DATA", "/.env", "/.git/config", "/con", "/CON.txt",
                             "/com1.log", "/lpt9", "/name.", "/name ", "/bad%zz", "relative.txt", "/nul%00.txt" })
        CHECK(!safeRelativePath(bad).has_value());
    CHECK(safeRelativePath("/console.txt").has_value());
    CHECK(safeRelativePath("/com10.txt").has_value());
}

